namespace C=strata::deepseek41::cuda;namespace K=strata::kernels;
constexpr int H=5120,V=129280,M=256,N=5,T=8;constexpr size_t HeadBytes=542976000,RawBytes=size_t(M)*V*2;
uint64_t primitive_values=0,pipeline_values=0,ids_count=0;
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
struct B{void*p{};size_t bytes;explicit B(size_t n):bytes(n){ck(cudaMalloc(&p,n));}~B(){cudaFree(p);}float*f(){return static_cast<float*>(p);}int32_t*i(){return static_cast<int32_t*>(p);}const uint16_t*h(){return static_cast<const uint16_t*>(p);}};
template<class A>void upload(B&b,const std::vector<A>&a,cudaStream_t s){need(a.size()*sizeof(A)<=b.bytes,"upload bounds");ck(cudaMemcpyAsync(b.p,a.data(),a.size()*sizeof(A),cudaMemcpyHostToDevice,s));ck(cudaStreamSynchronize(s));}
template<class A>std::vector<A>read(B&b,size_t n,cudaStream_t s){need(n*sizeof(A)<=b.bytes,"read bounds");std::vector<A>a(n);ck(cudaMemcpyAsync(a.data(),b.p,n*sizeof(A),cudaMemcpyDeviceToHost,s));ck(cudaStreamSynchronize(s));return a;}
template<class A>void eq(const std::vector<A>&a,const std::vector<A>&b,const char*s){need(a.size()==b.size(),"eq bounds");need(!std::memcmp(a.data(),b.data(),a.size()*sizeof(A)),s);}
std::vector<uint16_t>raw_weights(int seed){std::vector<uint16_t>a(size_t(M)*V);uint32_t st=80112+seed;for(size_t i=0;i<a.size();++i){st=st*1664525u+1013904223u;a[i]=uint16_t(0x3b00|(st&0x807fu));if(i%1024==0)a[i]=uint16_t(i%2048?1:0x80);if(i%16384==3)a[i]=0x8001;}return a;}
std::vector<float>expand(const std::vector<uint16_t>&a){std::vector<float>f(a.size());for(size_t i=0;i<a.size();++i){uint32_t u=uint32_t(a[i])<<16;std::memcpy(&f[i],&u,4);}return f;}
std::vector<uint8_t>head_weights(){std::vector<uint8_t>w(HeadBytes);uint32_t st=91112;for(auto&b:w){st=st*1664525u+1013904223u;b=uint8_t(st>>24);}for(size_t i=0;i<w.size();i+=210){__half d=__float2half_rn(.0001f*(1+(i/210)%7));std::memcpy(w.data()+i+208,&d,2);}return w;}
struct Capture{
 cudaGraph_t graph{};cudaGraphExec_t exec{};std::vector<cudaGraph_t>children;
 static void observe(void*p,void*g){static_cast<Capture*>(p)->children.push_back(static_cast<cudaGraph_t>(g));}
 template<class F>Capture(cudaStream_t s,F f){ck(cudaStreamBeginCapture(s,cudaStreamCaptureModeThreadLocal));f(this);ck(cudaStreamEndCapture(s,&graph));ck(cudaGraphInstantiate(&exec,graph,nullptr,nullptr,0));}
 ~Capture(){cudaGraphExecDestroy(exec);cudaGraphDestroy(graph);}
 void run(cudaStream_t s){ck(cudaGraphLaunch(exec,s));}
 void proof(const void*head,const void*w2,bool candidate,int count){int dense=0,conditionals=0;bool head_found=false;std::vector<cudaGraph_t>all{graph};if(candidate)all.insert(all.end(),children.begin(),children.end());for(auto g:all){size_t n=0;ck(cudaGraphGetNodes(g,nullptr,&n));std::vector<cudaGraphNode_t>nodes(n);ck(cudaGraphGetNodes(g,nodes.data(),&n));for(auto node:nodes){cudaGraphNodeType type;ck(cudaGraphNodeGetType(node,&type));if(type==cudaGraphNodeTypeConditional){++conditionals;continue;}if(type!=cudaGraphNodeTypeKernel)continue;cudaKernelNodeParams p{};ck(cudaGraphKernelNodeGetParams(node,&p));const char*name=nullptr;ck(cudaFuncGetName(&name,p.func));std::string k=name?name:"";void*first=nullptr;std::memcpy(&first,p.kernelParams[0],sizeof(first));if(k.find("mmvq")!=std::string::npos&&first==head)head_found=true;if((candidate&&k.find("bf16_markov_kernel")!=std::string::npos)||(!candidate&&k.find("dense_kernel")!=std::string::npos)){need(first==w2&&p.blockDim.x==256&&p.gridDim.x==V&&p.gridDim.y==1,"actual Markov pointer/grid not selected");++dense;}}}need(head_found,"actual full Q6 head pointer absent");need(dense==(candidate?count:1),"all candidate conditional W2 pointers not proven");if(candidate)need(children.size()==size_t(count==1?0:count)&&conditionals==int(children.size()),"candidate conditional hierarchy not complete");}
};
struct Stage{
 cudaStream_t stream{},aux[5]{};void*bodies[5];
 B w1{size_t(V)*M*4},w2{size_t(V)*M*4},raw{RawBytes},head{HeadBytes},gamma{H*4},cw{(H+M)*4},cb{4},residual{H*4*N*4},pre{4*N*4},anchor{4},primitive_input{M*T*4};
 B primitive[2]={B(size_t(V)*T*4),B(size_t(V)*T*4)};
 B x[2]={B(H*N*4),B(H*N*4)},normal[2]={B(H*N*4),B(H*N*4)},q[2]={B(K::native_q8_1_bytes(H,T)),B(K::native_q8_1_bytes(H,T))},il[2]={B(K::native_q8_1_il_bytes(H,T)),B(K::native_q8_1_il_bytes(H,T))},logits[2]={B(size_t(V)*N*4),B(size_t(V)*N*4)},markov[2]={B(M*4),B(M*4)},bias[2]={B(V*4),B(V*4)},conf[2]={B(N*4),B(N*4)},picks[2]={B(N*4),B(N*4)};
 int32_t*hostpick[2]{};float*hostconf[2]{};
 Stage(const std::vector<uint8_t>&hw,const std::vector<uint16_t>&rw,const std::vector<uint16_t>&row,const std::vector<float>*g=nullptr){ck(cudaStreamCreateWithFlags(&stream,cudaStreamNonBlocking));for(int i=0;i<5;++i){ck(cudaStreamCreateWithFlags(&aux[i],cudaStreamNonBlocking));bodies[i]=aux[i];}for(int v=0;v<2;++v){ck(cudaMallocHost(&hostpick[v],N*4));ck(cudaMallocHost(&hostconf[v],N*4));}upload(raw,rw,stream);upload(w2,expand(rw),stream);upload(w1,expand(row),stream);upload(head,hw,stream);std::vector<float>gm(H);for(int i=0;i<H;++i)gm[i]=1.f+.2f*std::sin(i*.01f);upload(gamma,g?*g:gm,stream);K::SamplerParams p;p.greedy=true;p.temperature=0;ck(cudaMemsetAsync(logits[0].p,0,V*4,stream));K::sample_tokens(logits[0].f(),1,V,nullptr,0,p,picks[0].i(),stream);ck(cudaStreamSynchronize(stream));}
 ~Stage(){cudaStreamSynchronize(stream);for(auto s:aux)cudaStreamDestroy(s);cudaStreamDestroy(stream);for(int v=0;v<2;++v){cudaFreeHost(hostpick[v]);cudaFreeHost(hostconf[v]);}}
 void input(int count,int stop,int phase,bool original_conf=false,const std::vector<float>*ac=nullptr){std::vector<float>r(size_t(H)*4*count),p(4*count),c(H+M,0.f);for(size_t i=0;i<r.size();++i)r[i]=phase?std::sin(float(i)*.013f+.31f*phase)*.2f:0.f;for(int t=0;t<count;++t){for(int h=0;h<4;++h){p[t*4+h]=h?.17f*h:1.f;r[size_t(t)*H*4+h*H]=0;}r[size_t(t)*H*4]=t==stop?-8.f:8.f;r[size_t(t)*H*4+33]=-0.f;r[size_t(t)*H*4+34]=std::ldexp(1.f,-140);if(phase==2)r[size_t(t)*H*4+57]=1e5f;}c[0]=1.f;upload(residual,r,stream);upload(pre,p,stream);upload(cw,original_conf?*ac:c,stream);upload(cb,std::vector<float>{0.f},stream);upload(anchor,std::vector<int32_t>{42+137*phase+stop+1},stream);}
 C::DraftHeadView view(int v){return {x[v].f(),w1.f(),w2.f(),cw.f(),nullptr,anchor.i(),logits[v].f(),markov[v].f(),bias[v].f(),conf[v].f(),picks[v].i(),H,V};}
 void body(int v,int n,Capture*trace){C::hc_pre(residual.f(),pre.f(),x[v].f(),H,n,stream);C::rms(x[v].f(),gamma.f(),normal[v].f(),H,n,1e-20f,stream);if(n>=5){K::native_quantize_q8_1_il_wide(normal[v].f(),q[v].p,il[v].p,H,n,stream);K::native_mmvq_il_wide(14,head.p,il[v].p,logits[v].f(),H,V,n,stream);}else if(n>1){K::native_quantize_q8_1_il(normal[v].f(),q[v].p,il[v].p,H,n,stream);K::native_mmvq_il(14,head.p,q[v].p,il[v].p,logits[v].f(),H,V,n,stream);}else{K::native_quantize_q8_1(normal[v].f(),q[v].p,H,n,stream);K::native_mmvq(14,head.p,q[v].p,logits[v].f(),H,V,n,stream);}if(v)C::conditional_draft_head_bf16(view(v),raw.h(),n,.75f,stream,bodies,Capture::observe,trace);else C::conditional_draft_head(view(v),n,.75f,stream,bodies);}
 void copy(int v,int n){ck(cudaMemcpyAsync(hostpick[v],picks[v].p,n*4,cudaMemcpyDeviceToHost,stream));ck(cudaMemcpyAsync(hostconf[v],conf[v].p,n*4,cudaMemcpyDeviceToHost,stream));ck(cudaStreamSynchronize(stream));}
 void verify(int n,int expected_stop=-2){eq(read<float>(x[0],H*n,stream),read<float>(x[1],H*n,stream),"collapsed x differs");eq(read<float>(normal[0],H*n,stream),read<float>(normal[1],H*n,stream),"RMS differs");eq(read<float>(logits[0],size_t(V)*n,stream),read<float>(logits[1],size_t(V)*n,stream),"all conditional logits/skippedtail differ");eq(read<float>(markov[0],M,stream),read<float>(markov[1],M,stream),"last gathered row differs");eq(read<float>(bias[0],V,stream),read<float>(bias[1],V,stream),"all last W2 bias differs");auto a=read<float>(conf[0],n,stream),b=read<float>(conf[1],n,stream);eq(a,b,"confidence differs");eq(read<int32_t>(picks[0],n,stream),read<int32_t>(picks[1],n,stream),"all picks/reset tail differ");if(expected_stop>=-1){int done=expected_stop<0?n:expected_stop+1;for(int t=0;t<done;++t)need(t==expected_stop?a[t]<.75f:a[t]>=.75f,"independent requested branch not exercised");for(int t=done;t<n;++t)need(a[t]==0.f,"unexecuted confidence not cleared");}pipeline_values+=size_t(n)*(2*H+V+1)+M+V;ids_count+=n;}
};
int main(int argc,char**argv){try{K::native_mmvq_set_multi_exact(true);bool actual=argc==4&&std::string(argv[1])=="--actual";std::vector<uint8_t>hw;std::vector<uint16_t>rw,row;std::vector<float>gm,ac;if(actual){std::ifstream h(argv[2],std::ios::binary);need(bool(h),"original target head fixture missing");hw.resize(HeadBytes);h.read(reinterpret_cast<char*>(hw.data()),hw.size());need(bool(h),"original target head short");std::ifstream f(argv[3],std::ios::binary);need(bool(f),"actual draft head fixture missing");rw.resize(size_t(M)*V);row.resize(size_t(M)*V);gm.resize(H);ac.resize(H+M);f.read(reinterpret_cast<char*>(rw.data()),RawBytes);f.read(reinterpret_cast<char*>(row.data()),RawBytes);f.read(reinterpret_cast<char*>(gm.data()),H*4);std::vector<uint16_t>bf(H+M);f.read(reinterpret_cast<char*>(bf.data()),bf.size()*2);ac=expand(bf);need(bool(f)&&f.peek()==std::char_traits<char>::eof(),"actual fixture size/order");}else{hw=head_weights();rw=raw_weights(1);row=raw_weights(2);}bool gate=true;
 for(int gpu=0;gpu<2;++gpu){ck(cudaSetDevice(gpu));int l2=0;ck(cudaDeviceGetAttribute(&l2,cudaDevAttrL2CacheSize,gpu));need(RawBytes<size_t(l2)&&RawBytes*2>size_t(l2)&&HeadBytes>2*size_t(l2),"actual storage/L2 regime absent");{
 Stage z(hw,rw,row,actual?&gm:nullptr);
 for(int nt=1;nt<=8;++nt){Capture old(z.stream,[&](Capture*){C::dense(z.w2.f(),z.primitive_input.f(),z.primitive[0].f(),M,V,nt,z.stream);}),next(z.stream,[&](Capture*){C::markov_bf16(z.raw.h(),z.primitive_input.f(),z.primitive[1].f(),V,nt,z.stream);});for(int phase=0;phase<3;++phase){std::vector<float>x(M*nt);for(size_t i=0;i<x.size();++i)x[i]=phase?std::sin(float(i)*.03f+.1f*phase)*.1f:0.f;for(int t=0;t<nt;++t){if(!actual||phase){x[t*M+3]=-0.f;x[t*M+4]=std::ldexp(1.f,-140);}if(phase==2)x[t*M+17]=1e5f;}upload(z.primitive_input,x,z.stream);old.run(z.stream);next.run(z.stream);ck(cudaStreamSynchronize(z.stream));eq(read<float>(z.primitive[0],size_t(nt)*V,z.stream),read<float>(z.primitive[1],size_t(nt)*V,z.stream),"original dense vs BF16 W2 primitive differs");primitive_values+=size_t(nt)*V;}}
 for(int n=1;n<=5;++n){Capture old(z.stream,[&](Capture*g){z.body(0,n,g);}),next(z.stream,[&](Capture*g){z.body(1,n,g);});old.proof(z.head.p,z.w2.p,false,n);next.proof(z.head.p,z.raw.p,true,n);for(int stop=-1;stop<n;++stop)for(int phase=0;phase<3;++phase){z.input(n,stop,phase);old.run(z.stream);z.copy(0,n);next.run(z.stream);z.copy(1,n);z.verify(n,stop);}if(actual){for(int phase=0;phase<3;++phase){z.input(n,-1,phase,true,&ac);old.run(z.stream);z.copy(0,n);next.run(z.stream);z.copy(1,n);z.verify(n);}}
 if(gpu==1&&n==5&&!actual&&!(argc==2&&std::string(argv[1])=="--correctness-only")){z.input(5,-1,1);auto run=[&](int v){ck(cudaSetDevice(gpu));if(v)next.run(z.stream);else old.run(z.stream);z.copy(v,5);};for(int i=0;i<8;++i)run(i%2);z.verify(5,-1);double total[2]={};int faster=0;for(int pair=0;pair<16;++pair){double ms[2];for(int order=0;order<2;++order){int v=(pair+order)%2;auto start=std::chrono::steady_clock::now();for(int k=0;k<4;++k)run(v);ms[v]=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/4;total[v]+=ms[v];}faster+=ms[1]<ms[0];z.verify(5,-1);std::cout<<"pair="<<pair<<" old_ms="<<ms[0]<<" raw_bf16_ms="<<ms[1]<<" ratio="<<ms[0]/ms[1]<<std::endl;}gate=total[0]/total[1]>1.05&&faster==16;std::cout<<std::setprecision(12)<<"GATE COMPLETE original draft HCpre/RMS/Q6targethead/conditional5-position Markov/confidence/add/greedy/D2Hpicks+confidence/sync NT5 pmin.75 all5confident GPU1; head542976000>2L2, F32W2="<<RawBytes*2<<">L2="<<l2<<">BF16W2="<<RawBytes<<"; all candidate child-matrix pointers and original256CTA proved; sum_old_ms="<<total[0]<<" sum_new_ms="<<total[1]<<" ratio="<<total[0]/total[1]<<" faster="<<faster<<"/16; componentONLY no model gain claim\n";}}
 std::cout<<"NUM gpu="<<gpu<<" primitive NT1..8 + complete conditional outputhead counts1..5/every-stop/3changedcaptures all-logits+bias+gather+confidence+picks BITWISE PASS"<<std::endl;
 }}std::cout<<"NUMERIC PASS primitive_F32="<<primitive_values<<" pipeline_F32="<<pipeline_values<<" IDs="<<ids_count<<" bothGPU; candidate all-child and original root pointer proof; no production edits\n";need(gate,"complete Markov BF16 head gate failed >1.05 and16fast required");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
